def _vary(qs):
    out = []
    for n, (s, q, o, c, r, f, i) in enumerate(qs):
        o = list(o)
        ans = o.pop(c)
        pos = (n * 5 + n // 4) % (len(o) + 1)
        o.insert(pos, ans)
        out.append((s, q, o, pos, r, f, i))
    return out
